<template><BioNexusDialog ref="box" title="Eliminar impuesto" kicker="Confirmacion" size="compact" @close="reset"><div class="delete-body"><p>Se eliminara fisicamente el impuesto <strong>{{record?.description}}</strong>.</p><div v-if="error" class="bio-nexus-message bio-nexus-message-error">{{error}}</div></div><template #footer><BioNexusActionButton variant="secondary" :disabled="saving" @click="close">Cancelar</BioNexusActionButton><BioNexusActionButton variant="danger" :loading="saving" @click="$emit('confirm',record)">Eliminar</BioNexusActionButton></template></BioNexusDialog></template>
<script setup>import{ref}from"vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";defineProps({saving:Boolean});defineEmits(["confirm"]);const box=ref(null),record=ref(null),error=ref("");function open(value){record.value=value;error.value="";box.value?.open()}function close(){box.value?.close()}function reset(){record.value=null;error.value=""}function setError(value){error.value=value}function clearError(){error.value=""}defineExpose({open,close,setError,clearError})</script><style scoped>.delete-body{display:grid;gap:var(--bio-nexus-space-3);padding:var(--bio-nexus-space-5);color:var(--bio-nexus-color-text-secondary)}</style>